Definition CONN_AT (B : Z) : Prop :=
  forall (itc vq vl err : Z) (pad7o : list byte) (ra sp gp tp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
