    (LF : list fframe) (m m1 : mem) (spa : Z) (gsz : nat) (gj j0 j64 j160 jr : list byte)
    (P E vp fld lo shi ff fp : Z) (vbs : list byte) (c c1 : pcore) (pad7 pad2 : list byte) (E0 : ecv) (g : bool) (h0 h1 h2 h3 : word),
  conn_lctx LF m m1 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P E vp vbs c1 pad7 pad2 E0 g lo shi ff fp h0 h1 h2 h3 j0 j64 j160 jr
            (OptItCells (ff + 32) itc vq vl err pad7o) ->
  dof_bpure sp spa gsz P E lo shi c fld vp vbs -> dof_core c c1 ->
  vp <= vq -> 1 <= vl -> vq + vl = itc -> itc <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) - itc < B -> 0 <= err < 256 ->
  evt asegs (dof_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc LF P E lo shi c pad7 pad2 vp vbs m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
             (wz ff) (wz 7) (wz (P + 76)) (wz (ff + 32)) (wz 5) (wz 10) (wz (Z.shiftr ff 3 + 2147450880)) (wz ALIT_CLOSE) (wz ASHADOW_BASE) (wz ff) t3 t4 t5 t6)
